#include <stdio.h>
#include <math.h>

#define EPS 1e-9

typedef struct {
    double x, y;
} Point;

int solveSegmentIntersection(Point p0, Point p1, Point p2, Point p3, Point *result) {
    double A1 = p1.y - p0.y;
    double B1 = p0.x - p1.x;
    double C1 = A1 * p0.x + B1 * p0.y;

    double A2 = p3.y - p2.y;
    double B2 = p2.x - p3.x;
    double C2 = A2 * p2.x + B2 * p2.y;

    double det = A1 * B2 - A2 * B1;

    if (fabs(det) < EPS) {
        // Parallel or collinear
        return 0;
    }

    double x = (B2 * C1 - B1 * C2) / det;
    double y = (A1 * C2 - A2 * C1) / det;

    // Check if intersection lies within both segments
    double minX1 = fmin(p0.x, p1.x) - EPS;
    double maxX1 = fmax(p0.x, p1.x) + EPS;
    double minY1 = fmin(p0.y, p1.y) - EPS;
    double maxY1 = fmax(p0.y, p1.y) + EPS;

    double minX2 = fmin(p2.x, p3.x) - EPS;
    double maxX2 = fmax(p2.x, p3.x) + EPS;
    double minY2 = fmin(p2.y, p3.y) - EPS;
    double maxY2 = fmax(p2.y, p3.y) + EPS;

    if (x >= minX1 && x <= maxX1 && y >= minY1 && y <= maxY1 &&
        x >= minX2 && x <= maxX2 && y >= minY2 && y <= maxY2) {
        result->x = x;
        result->y = y;
        return 1;
    }
    return 0;
}

int main() {
    Point p0, p1, p2, p3, intersection;

    scanf("%lf %lf", &p0.x, &p0.y);
    scanf("%lf %lf", &p1.x, &p1.y);
    scanf("%lf %lf", &p2.x, &p2.y);
    scanf("%lf %lf", &p3.x, &p3.y);

    if (solveSegmentIntersection(p0, p1, p2, p3, &intersection)) {
        printf("%.10f %.10f\n", intersection.x, intersection.y);
    } else {
        printf("No intersection\n");
    }

    return 0;
}

