#include <stdio.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

int main(void) {
    Point p0, p1, p2, p3;

    if (scanf("%lf %lf %lf %lf %lf %lf %lf %lf",
              &p0.x, &p0.y, &p1.x, &p1.y,
              &p2.x, &p2.y, &p3.x, &p3.y) != 8) {
        return 0;
    }

    double x1 = p0.x, y1 = p0.y;
    double x2 = p1.x, y2 = p1.y;
    double x3 = p2.x, y3 = p2.y;
    double x4 = p3.x, y4 = p3.y;

    double den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);

    if (fabs(den) < 1e-12) {
        return 0; /* Parallel or coincident; no unique intersection point */
    }

    double det1 = x1 * y2 - y1 * x2;
    double det2 = x3 * y4 - y3 * x4;

    double ix = (det1 * (x3 - x4) - (x1 - x2) * det2) / den;
    double iy = (det1 * (y3 - y4) - (y1 - y2) * det2) / den;

    printf("%.10f %.10f\n", ix, iy);
    return 0;
}

