void solve() {
    Point p0, p1, p2, p3;
    cin >> p0.x >> p0.y >> p1.x >> p1.y;
    cin >> p2.x >> p2.y >> p3.x >> p3.y;

    double denom = (p0.x - p1.x) * (p2.y - p3.y) - (p0.y - p1.y) * (p2.x - p3.x);
    double t_num = (p0.x - p2.x) * (p2.y - p3.y) - (p0.y - p2.y) * (p2.x - p3.x);
    double u_num = (p0.x - p2.x) * (p0.y - p1.y) - (p0.y - p2.y) * (p0.x - p1.x);

    if (fabs(denom) < 1e-9) {
        // Lines are parallel or collinear
        if (fabs(t_num) < 1e-9 && fabs(u_num) < 1e-9) {
            // Collinear - check overlap (simplified: output first endpoint if overlapping)
            // For simplicity, just say "No intersection" for collinear non-overlap
            cout << "No intersection" << endl;
        } else {
            cout << "Parallel" << endl;
        }
        return;
    }

    double t = t_num / denom;
    double u = u_num / denom;

    if (t < 0 || t > 1 || u < 0 || u > 1) {
        cout << "No intersection" << endl;
        return;
    }

    double ix = p0.x + t * (p1.x - p0.x);
    double iy = p0.y + t * (p1.y - p0.y);
    cout << fixed << setprecision(10) << ix << " " << iy << endl;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    solve();
    return 0;
}

