struct Point {
    double x, y;
    Point() {}
    Point(double x, double y) : x(x), y(y) {}
    Point operator + (const Point& other) const { return Point(x + other.x, y + other.y); }
    Point operator - (const Point& other) const { return Point(x - other.x, y - other.y); }
    Point operator * (double k) const { return Point(x * k, y * k); }
};

double cross(const Point& a, const Point& b) {
    return a.x * b.y - a.y * b.x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    Point p0, p1, p2, p3;
    cin >> p0.x >> p0.y >> p1.x >> p1.y >> p2.x >> p2.y >> p3.x >> p3.y;

    Point r = p1 - p0;
    Point s = p3 - p2;

    // Intersection of lines:
    // p0 + t*r = p2 + u*s
    // t = cross(p2 - p0, s) / cross(r, s)
    double denom = cross(r, s);
    double t = cross(p2 - p0, s) / denom;

    Point inter = p0 + r * t;

    cout << fixed << setprecision(10) << inter.x << " " << inter.y << "\n";
    return 0;
}

import java.util.Scanner;

public class SegmentIntersection {
    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double xp0 = sc.nextDouble(), yp0 = sc.nextDouble();
        double xp1 = sc.nextDouble(), yp1 = sc.nextDouble();
        double xp2 = sc.nextDouble(), yp2 = sc.nextDouble();
        double xp3 = sc.nextDouble(), yp3 = sc.nextDouble();

        Point p0 = new Point(xp0, yp0);
        Point p1 = new Point(xp1, yp1);
        Point p2 = new Point(xp2, yp2);
        Point p3 = new Point(xp3, yp3);

        Point intersection = getIntersection(p0, p1, p2, p3);
        if (intersection != null) {
            System.out.printf("%.10f %.10f%n", intersection.x, intersection.y);
        }
        sc.close();
    }

    static Point getIntersection(Point p0, Point p1, Point p2, Point p3) {
        double d1x = p1.x - p0.x, d1y = p1.y - p0.y;
        double d2x = p3.x - p2.x, d2y = p3.y - p2.y;

        double denom = d1x * d2y - d1y * d2x;
        if (Math.abs(denom) < 1e-12) {
            // Parallel or collinear
            return null;
        }

        double t = ((p2.x - p0.x) * d2y - (p2.y - p0.y) * d2x) / denom;
        double u = ((p2.x - p0.x) * d1y - (p2.y - p0.y) * d1x) / denom;

        if (t < 0 || t > 1 || u < 0 || u > 1) {
            return null; // Intersection outside segments
        }

        double ix = p0.x + t * d1x;
        double iy = p0.y + t * d1y;
        return new Point(ix, iy);
    }
}

