        double dy2 = yp3 - yp2;

        double D = dx1 * dy2 - dy1 * dx2;

        if (Math.abs(D) < 1e-10) {
            // Parallel or coincident - handle edge case
            System.out.println("No intersection or infinite intersections");
            return;
        }

        double t = ((xp2 - xp0) * dy2 - (yp2 - yp0) * dx2) / D;

        double ix = xp0 + t * dx1;
        double iy = yp0 + t * dy1;

        System.out.printf("%.2f %.2f%n", ix, iy);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            double val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }

            if (c == '.') {
                double mul = 0.1;
                c = read();
                while (c >= '0' && c <= '9') {
                    val += (c - '0') * mul;
                    mul *= 0.1;
                    c = read();
                }
            }

            return val * sign;
        }
    }

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static Point sub(Point a, Point b) {
        return new Point(a.x - b.x, a.y - b.y);
    }

    static double cross(Point a, Point b) {
        return a.x * b.y - a.y * b.x;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        Point p0 = new Point(fs.nextDouble(), fs.nextDouble());
        Point p1 = new Point(fs.nextDouble(), fs.nextDouble());
        Point p2 = new Point(fs.nextDouble(), fs.nextDouble());
        Point p3 = new Point(fs.nextDouble(), fs.nextDouble());

        Point r = sub(p1, p0);
        Point s = sub(p3, p2);

        double t = cross(sub(p2, p0), s) / cross(r, s);

        Point ans = new Point(p0.x + r.x * t, p0.y + r.y * t);

        System.out.printf(Locale.US, "%.10f %.10f%n", ans.x, ans.y);
    }
}
